 const welcome='<div class="chat-line"><span class="bot-icon" style="width:26px;height:26px;font-size:13px">🤖</span><div class="chat-bubble">Hi! I’m your BudgetBuddy assistant 💗 I can help you find products, compare prices, plan lists and discover promo codes.</div></div>';
