 $('right').innerHTML=`<section class="surface assistant-panel conversation-panel ${state.enteringConversation?'conversation-enter':''}"><div class="chat-head"><span class="bot-icon">🤖</span><div style="flex:1"><div class="chat-title">BudgetBuddy assistant</div><div class="chat-sub"><span class="online"></span>${enabled?`Answers via ${esc(state.aiProvider)}`:'Live web search and AI answers'}</div></div><span class="${enabled?'live-pill':'status-pill'}">${enabled?'AI configured':'AI needed for live search'}</span></div><div class="chat-box" id="chat-scroll" aria-live="polite">${chats}${state.pending?'<div class="chat-line"><div class="chat-bubble">Searching published listings…</div></div>':''}${state.chatPending?`<div class="chat-line"><div class="chat-bubble">${esc(state.chatPendingText||'Thinking…')}</div></div>`:''}</div><div class="quick-actions"><button data-action="help">✨ What can you do?</button></div><form class="chat-input" id="chat-form"><label class="sr-only" for="chat-text">Ask BudgetBuddy</label><input type="text" id="chat-text" maxlength="2000" placeholder="Ask me anything..."/><button class="chat-send" type="submit" aria-label="Send message" ${state.chatPending?'disabled':''}>➤</button></form><div class="chat-privacy">${enabled?'Live answers use your configured provider web-search tool.':'Configure AI_BASE_URL, AI_API_KEY, and AI_MODEL on the server to enable web search and AI answers.'} Never share passwords or payment details.</div></section>${shoppingList}`;
 state.enteringConversation=false;
